def separate_paren_groups(paren_string: str) -> list:
    """
    Separate top-level balanced parentheses groups from the input string,
    ignoring any spaces. Returns a list of strings representing each group.

    :param paren_string: Input string that contains multiple groups of nested parentheses.
    :return: List of strings, each representing a top-level balanced parentheses group.
    """
    result = []
    group = []
    depth = 0
    for ch in paren_string:
        if ch.isspace():
            continue
        if ch not in ('(', ')'):
            continue
        group.append(ch)
        if ch == '(':
            depth += 1
        else:
            depth -= 1
            if depth < 0:
                raise ValueError("Unbalanced parentheses detected.")
        if depth == 0 and group:
            result.append(''.join(group))
            group = []
    if depth != 0:
        raise ValueError("Unbalanced parentheses at end of input.")
    return result

