def find_topmost_carpet(n, carpets, point) -> int:
    """
    Returns the index (1‑based) of the topmost carpet covering a point.
    If no carpet covers the point, returns -1.
    """
    # Basic validation
    try:
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if not isinstance(carpets, list) or len(carpets) != n:
            raise ValueError("carpets must be a list of length n")
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError("point must be a tuple of length 2")
    except Exception as e:
        # For any invalid input we simply return -1 as no carpet can be chosen
        return -1

    x, y = point
    # Iterate from topmost to bottommost
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        # Ensure carpet specs are integers
        if not all(isinstance(v, int) for v in (a, b, g, k)):
            continue
        # Check if point lies inside the rectangle (inclusive boundaries)
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1  # 1‑based indexing

    return -1

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each path starts at (1, 1) and ends at (N, N), moving only right or down.
    If both paths visit the same cell, the cell's value is counted only once.
    """
    if N <= 0:
        return 0

    # Build the grid and fill it with the provided values
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = value

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    total_steps = 2 * (N - 1)
    # dp[i1][i2] = maximum sum when first path is at (i1, j1) and second at (i2, j2)
    # where j1 = step - i1 and j2 = step - i2
    # We keep only current and next step matrices to save memory
    dp = [[-float('inf')] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    for step in range(1, total_steps + 1):
        new_dp = [[-float('inf')] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, step + 1 - N)
        i_max = min(N, step + 1)
        for i1 in range(i_min, i_max + 1):
            j1 = step + 1 - i1
            if not (1 <= j1 <= N):
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step + 1 - i2
                if not (1 <= j2 <= N):
                    continue
                # Determine the best previous state
                best_prev = -float('inf')
                for di1 in (-1, 0):
                    prev_i1 = i1 + di1
                    if not (1 <= prev_i1 <= N):
                        continue
                    for di2 in (-1, 0):
                        prev_i2 = i2 + di2
                        if not (1 <= prev_i2 <= N):
                            continue
                        val = dp[prev_i1][prev_i2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == -float('inf'):
                    continue
                cell_sum = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell_sum += grid[i2][j2]
                new_dp[i1][i2] = best_prev + cell_sum
        dp = new_dp

    result = dp[N][N]
    return int(result) if result != -float('inf') else 0

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (list[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"

    terms = []
    first = True

    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign and absolute value
        sign = "-" if coeff < 0 else "+"
        abs_coeff = abs(coeff)

        # Format coefficient
        if abs_coeff == 1 and degree != 0:
            coeff_part = ""  # omit 1 for non-constant terms
        else:
            coeff_part = str(abs_coeff)

        # Format variable part
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        term = f"{coeff_part}{var_part}"

        if first:
            # No leading '+' for the first positive term
            if coeff < 0:
                terms.append("-" + term)
            else:
                terms.append(term)
            first = False
        else:
            terms.append(sign + term)

    # If all terms were zero, return "0"
    if not terms:
        return "0"

    return "".join(terms)

