def calculate_arrangements(n, m, a) -> int:
    """
    Compute the number of ways to arrange m pots of flowers using up to n types,
    where the ith type can have at most a[i] pots, and the arrangement must be in
    increasing order of flower types.

    :param n: int - number of flower types available.
    :param m: int - total number of flower pots to arrange.
    :param a: list[int] - maximum number of pots for the ith type of flower.
    :return: int - number of distinct arrangements modulo (10^6 + 7).
    """
    MOD = 10**6 + 7
    try:
        if not isinstance(n, int) or not isinstance(m, int) or not isinstance(a, list):
            raise TypeError("Invalid argument types.")
        if n != len(a):
            raise ValueError("Length of a must equal n.")
        if m < 0:
            raise ValueError("m must be non-negative.")
        for ai in a:
            if not isinstance(ai, int) or ai < 0:
                raise ValueError("All elements of a must be non-negative integers.")
    except Exception as e:
        raise e

    # If sum of all limits is less than m, impossible to fill pots
    if sum(a) < m:
        return 0

    prev = [0] * (m + 1)
    prev[0] = 1
    for ai in a:
        prefix = [0] * (m + 1)
        prefix[0] = prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + prev[j]) % MOD
        curr = [0] * (m + 1)
        for j in range(m + 1):
            low = j - ai
            if low > 0:
                curr[j] = (prefix[j] - prefix[low - 1]) % MOD
            else:
                curr[j] = prefix[j] % MOD
        prev = curr
    return prev[m] % MOD

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0
    # Longest Increasing Subsequence lengths ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest Decreasing Subsequence lengths starting at each index (strictly decreasing)
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Find maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # count the peak once
        if bitonic_len > max_len:
            max_len = bitonic_len
    return n - max_len

